// Prepares the repo-root `openapi.json` for Apple's swift-openapi-generator.
//
// The generator silently drops every property written the way Effect's
// generator writes nullable ones — `anyOf: [X, { type: "null" }]` — which
// would leave `User` without `displayName`, `avatarUrl`, … So this rewrites
// those unions into forms the generator understands, and narrows the
// number-typed ids/timestamps/counts to integers so Swift gets `Int`, not
// `Double`. Nothing else changes; the output is a gitignored build input
// (ios/ChatAPI/Sources/ChatAPI/openapi.json), regenerated by `xcodegen`
// (preGenCommand) and by ios/scripts/test.sh.
//
//   bun ios/scripts/prepare-openapi.ts [input.json] [output.json]
import { mkdirSync, readFileSync, writeFileSync } from "node:fs";
import path from "node:path";
import { fileURLToPath } from "node:url";

type Json = null | boolean | number | string | Json[] | { [key: string]: Json };
type Schema = { [key: string]: Json };

const here = path.dirname(fileURLToPath(import.meta.url));
const input = process.argv[2] ?? path.join(here, "..", "..", "openapi.json");
const output =
  process.argv[3] ??
  path.join(here, "..", "ChatAPI", "Sources", "ChatAPI", "openapi.json");

const isObject = (value: Json | undefined): value is Schema =>
  typeof value === "object" && value !== null && !Array.isArray(value);

const isNullSchema = (value: Json): boolean =>
  isObject(value) && value["type"] === "null";

// Property names whose `number` is always a whole number on the wire.
const INTEGER_NAME =
  /^(id|count|limit|size|width|height|maxPlayers|minPlayers|maxUses|round|turn|place|rank|serverNow)$|(Id|Ids|At|Count)$/;

const without = (schema: Schema, key: string): Schema =>
  Object.fromEntries(Object.entries(schema).filter(([name]) => name !== key));

// The `type` of a `#/components/schemas/X` target (objects, unless it's an
// enum or alias of something else).
function refType(ref: string): string {
  const target = (schemas[ref.split("/").pop() ?? ""] ?? {})["type"];
  return typeof target === "string" ? target : "object";
}

// `anyOf: [A, B, null]` → `A`/`anyOf: [A, B]`, nullable.
function flattenNullable(schema: Schema): Schema {
  const members = schema["anyOf"];
  if (!Array.isArray(members) || !members.some(isNullSchema)) return schema;
  const rest = without(schema, "anyOf");
  const present = members.filter((member) => !isNullSchema(member));
  if (present.length === 1 && isObject(present[0])) {
    const only = present[0];
    if (typeof only["type"] === "string") {
      return { ...only, ...rest, type: [only["type"], "null"] };
    }
    if (Array.isArray(only["type"])) {
      // Already nullable from an inner union.
      const types = only["type"];
      return {
        ...only,
        ...rest,
        type: types.includes("null") ? types : [...types, "null"],
      };
    }
    if (typeof only["$ref"] === "string") {
      // A nullable reference: `type` must say what the target is, plus null.
      return { ...only, ...rest, type: [refType(only["$ref"]), "null"] };
    }
  }
  return { ...rest, anyOf: [...present, { type: "null" }] };
}

// `allOf: [{ pattern }]` on a string only adds a constraint, but the generator
// wraps it in a one-field struct. The client validates its own input, so drop it.
function dropConstraintOnlyAllOf(schema: Schema): Schema {
  const members = schema["allOf"];
  if (!Array.isArray(members)) return schema;
  const constraintOnly = members.every(
    (member) => isObject(member) && !("$ref" in member) && !("type" in member),
  );
  if (!constraintOnly) return schema;
  return without(schema, "allOf");
}

function rewrite(node: Json): Json {
  if (Array.isArray(node)) return node.map(rewrite);
  if (!isObject(node)) return node;
  const out: Schema = {};
  for (const [name, value] of Object.entries(node)) {
    out[name] = rewrite(value);
  }
  let result = dropConstraintOnlyAllOf(flattenNullable(out));
  // A union can nest another (`anyOf: [anyOf: [..., null], null]`).
  if (result !== out) result = flattenNullable(result);
  return result;
}

// Number → integer by property name, applied where properties are declared.
function narrowProperties(node: Json): Json {
  if (Array.isArray(node)) return node.map(narrowProperties);
  if (!isObject(node)) return node;
  const out: Schema = {};
  for (const [name, value] of Object.entries(node)) {
    if (name === "properties" && isObject(value)) {
      const props: Schema = {};
      for (const [prop, schema] of Object.entries(value)) {
        props[prop] = INTEGER_NAME.test(prop)
          ? toInteger(narrowProperties(schema))
          : narrowProperties(schema);
      }
      out[name] = props;
    } else {
      out[name] = narrowProperties(value);
    }
  }
  return out;
}

function toInteger(schema: Json): Json {
  if (!isObject(schema)) return schema;
  const type = schema["type"];
  if (type === "number") return { ...schema, type: "integer" };
  if (Array.isArray(type) && type.includes("number")) {
    return {
      ...schema,
      type: type.map((t) => (t === "number" ? "integer" : t)),
    };
  }
  if (Array.isArray(schema["items"])) return schema;
  if (isObject(schema["items"])) {
    return { ...schema, items: toInteger(schema["items"]) };
  }
  return schema;
}

const spec = JSON.parse(readFileSync(input, "utf8")) as Json;
const schemas: Record<string, Schema> = {};
if (isObject(spec) && isObject(spec["components"])) {
  const declared = spec["components"]["schemas"];
  if (isObject(declared)) {
    for (const [name, schema] of Object.entries(declared)) {
      if (isObject(schema)) schemas[name] = schema;
    }
  }
}
const prepared = narrowProperties(rewrite(spec));
mkdirSync(path.dirname(output), { recursive: true });
writeFileSync(output, JSON.stringify(prepared, null, 2) + "\n");
